 * override the destination (e.g. once SFCC-880/SFCC-63 land for real), extending this component
 * with an optional override prop is a small, additive change — not a reason to invent one now for
 * a caller that doesn't exist yet (conventions.md's DRY/KISS guidance against speculative
 * abstraction).
 */
export const ZimmCartButtonGroup = () => {
  const intl = useIntl();
  const styles = useStyleConfig(ZIMM_CART_BUTTON_GROUP_RECIPE);
  const { checkoutOwner } = useCountryConfig();
  const navigate = useNavigation() as NavigateFn;

  // 'global-e' (HK, ME, and the not-yet-live en-ca/en-ch) is the only checkoutOwner value that
  // hides the express buttons — see this file's decision log, item 2, for why 'hybrid' (US)
  // groups with 'sfcc' as domestic here.
  const isInternational = checkoutOwner === 'global-e';

  const handleCheckoutClick = () => {
    if (isInternational) {
      navigateInternationalCheckoutStub(navigate);
      return;
    }
    navigate('/checkout');
  };

  return (
