import { useRef, useState } from 'react';

// 'unavailable' shown until HPC-036 (Omneo) lands; prevents false "You're on the list!" feedback.
// 'success'/'error' set only after a confirmed/failed Omneo response (post HPC-036).
export type SubmitState = 'idle' | 'unavailable' | 'success' | 'error';

// The HPC-036 sign-up payload: footer email (HPC-034) + modal names (HPC-035).
// Assembled across two steps, POSTed to Omneo → Emarsys when the integration lands.
type PendingSignup = { email: string; firstName: string; lastName: string };

type UseSubscribeSectionParams = {
  /** Forces the post-submit success state up front. For Storybook/tests only. */
  initialSubscribed?: boolean;
  /** Opt in to the HPC-035 name-capture modal instead of the placeholder path. */
  enableNameCapture?: boolean;
};

type UseSubscribeSectionReturn = {
  submitState: SubmitState;
  modalOpen: boolean;
  closeModal: () => void;
  handleEmailSubmit: (email: string) => void;
  handleModalSubmit: (firstName: string, lastName: string) => void;
};

/**
 * State machine for the subscribe section: the idle/unavailable/success/error submit states,
 * the optional HPC-035 name-capture modal, and the pending-signup payload assembled across both
 * steps.
 *
 * Extracted from ZimmSubscribeSection per components.md's extract-to-hook threshold (≥2 related
 * useState that change together — submitState and modalOpen here, plus the pendingSignupRef).
 *
 * @param params initialSubscribed (Storybook/test only) and enableNameCapture (HPC-035 opt-in)
 * @returns current submit/modal state plus the two submit handlers
 */
export const useSubscribeSection = ({
  initialSubscribed = false,
  enableNameCapture = false,
}: UseSubscribeSectionParams): UseSubscribeSectionReturn => {
  // Map the Storybook-only `initialSubscribed` flag to the success state.
  // Post HPC-036, 'success' will only be reached via a confirmed Omneo response.
  const [submitState, setSubmitState] = useState<SubmitState>(initialSubscribed ? 'success' : 'idle');
  // Ref, not state: nothing renders from it, so a re-render on capture would be wasted. The
  // footer input unmounts once submitState leaves 'idle', so the email must be captured here at
  // step 1 or it is unrecoverable at step 2.
  const pendingSignupRef = useRef<PendingSignup>({ email: '', firstName: '', lastName: '' });
  const [modalOpen, setModalOpen] = useState(false);

  const handleEmailSubmit = (email: string) => {
    pendingSignupRef.current.email = email;
    if (enableNameCapture) {
      setModalOpen(true);
      return;
    }
    // Descoped path, and the default. SFCC-55's AC scopes this section to "an email input field
    // and submit button as a placeholder component" and defers the Omneo sign-up to a separate
    // story. The name-capture modal is HPC-035/HPC-037 but has no Figma node — all nine of its
    // theme parts are undesigned. So it does not ship enabled: submitting a valid email goes
    // straight to the placeholder message. Flip enableNameCapture on once Kiera supplies the
    // design and HPC-035 is scheduled; the modal and its coverage are already built and tested.
    setSubmitState('unavailable');
    pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
  };

  const handleModalSubmit = (firstName: string, lastName: string) => {
    pendingSignupRef.current = { ...pendingSignupRef.current, firstName, lastName };
    // PLACEHOLDER until HPC-036 (Omneo integration) lands: POST pendingSignupRef.current here.
    // On confirmed response → setSubmitState('success'). On failure → setSubmitState('error').
    // 'unavailable' is shown until the integration is live; never show false success.
    setModalOpen(false);
    setSubmitState('unavailable');
    // Nothing was sent, so nothing needs retaining — the record holds customer PII and there is
    // no request for it to outlive. When HPC-036 adds the POST above, this reset stays; it just
    // moves to after a confirmed response. React memory only, never storage, never logged.
    pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
  };

  return {
    submitState,
    modalOpen,
    // A Cancel (as opposed to a submit) is still an exit path for the captured email, so it
    // gets the same clear as handleModalSubmit — a shopper who backs out shouldn't leave PII
    // sitting in memory waiting for a signup that never completes.
    closeModal: () => {
      setModalOpen(false);
      pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
    },
    handleEmailSubmit,
    handleModalSubmit,
  };
};

