import React, {useState, useEffect, useRef, useMemo, Component} from 'react'
import {useIntl, FormattedMessage} from 'react-intl'
import {useLocation} from 'react-router-dom'
import {Helmet} from 'react-helmet'
import {Text, Button, Box} from '@salesforce/retail-react-app/app/components/shared/ui'
import {useAccessToken, useShopperBasketsV2Mutation} from '@salesforce/commerce-sdk-react'
import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation'
import {useCurrentBasket} from '@salesforce/retail-react-app/app/hooks/use-current-basket'
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site'
import {getAssetUrl} from '@salesforce/pwa-kit-react-sdk/ssr/universal/utils'
import {
    ToggleCard,
    ToggleCardEdit
} from '@salesforce/retail-react-app/app/components/toggle-card'
import {useCheckout} from '@salesforce/retail-react-app/app/pages/checkout/util/checkout-context'
import {normalizeStateCode} from './normalizeStateCode'

// Use require() to avoid ES-module interop issues with the Adyen webpack bundle
// eslint-disable-next-line @typescript-eslint/no-var-requires
const AdyenCheckout: React.ComponentType<any> | undefined = (require('@adyen/adyen-salesforce-pwa') as any).AdyenCheckout

type AdyenErrorBoundaryProps = {onError: () => void; children: React.ReactNode}
type AdyenErrorBoundaryState = {hasError: boolean}

// Catches synchronous React render errors inside the Adyen bundle that cannot be
// surfaced via the onError prop (e.g. undefined component from a bad config spread).
class AdyenErrorBoundary extends Component<AdyenErrorBoundaryProps, AdyenErrorBoundaryState> {
    constructor(props: AdyenErrorBoundaryProps) {
        super(props)
        this.state = {hasError: false}
    }

    static getDerivedStateFromError(): AdyenErrorBoundaryState {
        return {hasError: true}
    }

    componentDidCatch(error: Error, info: React.ErrorInfo): void {
        // eslint-disable-next-line no-console
        console.error('[AdyenErrorBoundary] caught:', error.message, '\nComponent stack:', info.componentStack)
        this.props.onError()
    }

    render(): React.ReactNode {
        if (this.state.hasError) return null
        return this.props.children
    }
}

const Payment = () => {
    const {formatMessage} = useIntl()
    const {step, STEPS, goToStep} = useCheckout()
    const {getTokenWhenReady} = useAccessToken()
    const navigate = useNavigation()
    const {data: basket} = useCurrentBasket()
    const {site, locale} = useMultiSite()
    const [authToken, setAuthToken] = useState<string | null>(null)
    const [tokenError, setTokenError] = useState(false)
    const [adyenError, setAdyenError] = useState(false)
    // Composite key (basketId:normalised-address) that must match currentBillingKey before
    // Adyen renders. Prevents the dropin from staying mounted while a billing re-sync is pending
    // after the shopper changes their shipping address for the same basket.
    const [billingReadyKey, setBillingReadyKey] = useState<string | null>(null)

    // getAssetUrl reads window.Progressive.buildOrigin (set by PWA Kit SSR); absent in Storybook/test
    const adyenCssHref = typeof window !== 'undefined' && (window as Window & {Progressive?: unknown}).Progressive
        ? getAssetUrl('static/adyen.css')
        : undefined

    // basket is typed as the SFCC Basket entity; commerce-sdk-isomorphic's generated
    // types don't export a standalone Basket type we can import directly, so any is needed.
    const basketId: string | undefined = (basket as any)?.basketId
    const shippingAddress: Record<string, unknown> | undefined =
        (basket as any)?.shipments?.[0]?.shippingAddress

    const {mutateAsync: updateBillingAddressForBasket} = useShopperBasketsV2Mutation(
        'updateBillingAddressForBasket'
    )

    // The key for the currently-synced billing state. Used in the render gate so that
    // when shippingAddress changes for the same basket, Adyen unmounts immediately while
    // the new updateBillingAddressForBasket call is in flight.
    const currentBillingKey = useMemo(() => {
        if (!basketId || !shippingAddress) return null
        const {addressId, creationDate, lastModified, preferred, ...address} = shippingAddress
        address.stateCode = normalizeStateCode(address.stateCode, address.countryCode)
        const addressKey = JSON.stringify(Object.fromEntries(Object.entries(address).sort()))
        return `${basketId}:${addressKey}`
    }, [basketId, shippingAddress]) // eslint-disable-line react-hooks/exhaustive-deps

    // Maps basketId → serialised normalised address to detect address changes within
    // the same basket (updateShippingAddressForShipment keeps basketId constant).
    const billedAddresses = useRef<Map<string, string>>(new Map())
    // Per-basket promise chain so concurrent address changes don't fire parallel
    // updateBillingAddressForBasket calls — SFCC optimistic locking 409s on concurrent
    // mutations for the same basket.
    const billingQueue = useRef<Map<string, Promise<void>>>(new Map())

    useEffect(() => {
        let cancelled = false
        getTokenWhenReady().then((token: string) => {
            if (!cancelled) setAuthToken(token)
        }).catch(() => {
            if (!cancelled) setTokenError(true)
        })
        return () => {
            cancelled = true
        }
    }, []) // eslint-disable-line react-hooks/exhaustive-deps

    // Copy shipping address to billing address before rendering Adyen.
    // Normalize and compute addressKey first so we can detect address changes on the
    // same basket (updateShippingAddressForShipment keeps basketId constant).
    useEffect(() => {
        if (!basketId || !shippingAddress) return
        const {addressId, creationDate, lastModified, preferred, ...address} = shippingAddress
        address.stateCode = normalizeStateCode(address.stateCode, address.countryCode)
        const addressKey = JSON.stringify(Object.fromEntries(Object.entries(address).sort()))
        const compositeKey = `${basketId}:${addressKey}`
        if (billedAddresses.current.get(basketId) === addressKey) {
            setBillingReadyKey(compositeKey)
            return
        }
        let active = true
        const prev = billingQueue.current.get(basketId) ?? Promise.resolve()
        billingQueue.current.set(
            basketId,
            prev.then(() => {
                if (!active) return
                return updateBillingAddressForBasket({
                    body: address as any, // eslint-disable-line @typescript-eslint/no-explicit-any
                    parameters: {basketId}
                }).then(() => {
                    billedAddresses.current.set(basketId, addressKey)
                    if (active) setBillingReadyKey(compositeKey)
                }).catch(() => {
                    if (active) setAdyenError(true)
                })
            })
        )
        return () => {
            active = false
        }
    }, [basketId, shippingAddress]) // eslint-disable-line react-hooks/exhaustive-deps

    const {search} = useLocation()
    // When a redirect payment (Klarna, PayPal, 3DS) fails and returns to checkout,
    // Adyen pushes ?orderNo=<id> into the URL via window.history.pushState so the
    // component can cancel the reserved order. Read it here so the AdyenCheckout
    // component can pass it through to the cancel endpoint rather than relying solely
    // on the basket's c_orderNo attribute (which may be null if OCAPI is unavailable).
    const orderNo = useMemo(() => new URLSearchParams(search).get('orderNo') ?? '', [search])

    const customerId: string | undefined = (basket as any)?.customerInfo?.customerId

    // Adyen needs a locale with a country suffix (e.g. 'en-AU') to derive the
    // countryCode for payment methods. ZimmermannAU's locale id is just 'en',
    // so enrich it with the shipping address country code when there's no suffix.
    const shippingCountryCode: string | undefined = shippingAddress?.countryCode as string | undefined // shippingAddress is Record<string,unknown>; countryCode is always a string when present
    const adyenLocale =
        locale && shippingCountryCode && !locale.id?.includes('-')
            ? {...locale, id: `${locale.id}-${shippingCountryCode}`}
            : locale

    return (
        <>
        {adyenCssHref && (
            <Helmet>
                <link rel="stylesheet" id="adyen-checkout-css" href={adyenCssHref} />
            </Helmet>
        )}
        <ToggleCard
            id="step-3"
            title={formatMessage({defaultMessage: 'Payment', id: 'checkout_payment.title.payment'})}
            editing={step === STEPS.PAYMENT}
            onEdit={() => goToStep(STEPS.PAYMENT)}
            editLabel={formatMessage({
                defaultMessage: 'Edit Payment Info',
                id: 'toggle_card.action.editPaymentInfo'
            })}
        >
            <ToggleCardEdit>
                {(tokenError || adyenError) && (
                    <Box>
                        <Text role="alert" color="red.500" mb={3}>
                            <FormattedMessage
                                defaultMessage="Unable to load payment. Please refresh and try again."
                                id="checkout_payment.error.token_failed"
                            />
                        </Text>
                        <Button variant="outline" onClick={() => window.location.reload()}>
                            <FormattedMessage
                                defaultMessage="Refresh"
                                id="checkout_payment.action.refresh"
                            />
                        </Button>
                    </Box>
                )}
                {AdyenCheckout && authToken && basket && !adyenError && billingReadyKey === currentBillingKey && currentBillingKey !== null && (
                    <AdyenErrorBoundary onError={() => setAdyenError(true)}>
                        <AdyenCheckout
                            authToken={authToken}
                            customerId={customerId}
                            site={site}
                            locale={adyenLocale}
                            navigate={navigate}
                            basket={basket}
                            orderNo={orderNo}
                            onError={[(error: any) => {
                                // Non-fatal errors the Adyen dropin handles internally:
                                // SCRIPT_ERROR — a payment method's JS SDK failed to load (e.g. Apple Pay
                                //   blocked by CSP); the dropin removes that method, others still work.
                                // CANCEL — fired when a payment sheet is dismissed. The Adyen cancel
                                //   handler (LC) calls paymentCancel server-side and navigates to
                                //   /checkout?error=true on success. If paymentCancel returns 400
                                //   (ORDER_NOT_FOUND — the pre-reserved c_orderNo was never promoted to
                                //   a real SFCC order because payment failed before createOrderUsingOrderNo),
                                //   LC's catch block skips navigation. We navigate here as a safety net so
                                //   the user is not left on a broken dropin state. If LC succeeds, its own
                                //   navigate(/checkout?error=true&newBasketId=...) fires after ours and the
                                //   router applies both in sequence (the second, richer URL wins).
                                const errorName = error?.errorType ?? error?.name
                                if (errorName === 'SCRIPT_ERROR') return
                                if (errorName === 'CANCEL') {
                                    navigate('/checkout?error=true')
                                    return
                                }
                                setAdyenError(true)
                            }]}
                        />
                    </AdyenErrorBoundary>
                )}
            </ToggleCardEdit>
        </ToggleCard>
        </>
    )
}

export default Payment

